import{_ as d,o,c as a,ag as t}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"字段命名策略扩展","description":"","frontmatter":{},"headers":[],"relativePath":"zh/framework/field-name-strategies.md","filePath":"zh/framework/field-name-strategies.md","lastUpdated":1794489741000}'),c={name:"zh/framework/field-name-strategies.md"};function s(l,e,i,r,n,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="字段命名策略扩展" tabindex="-1">字段命名策略扩展 <a class="header-anchor" href="#字段命名策略扩展" aria-label="Permalink to &quot;字段命名策略扩展&quot;">​</a></h1><p>EasyYapi 内置了 9 个可选的 <code>field.name</code> 扩展，把导出的字段名统一转换为指定的命名风格。它们自 v3.2.7 起提供，<strong>默认全部关闭</strong>。</p><h2 id="可用扩展" tabindex="-1">可用扩展 <a class="header-anchor" href="#可用扩展" aria-label="Permalink to &quot;可用扩展&quot;">​</a></h2><table tabindex="0"><thead><tr><th>扩展 code</th><th>规则值</th><th>示例</th></tr></thead><tbody><tr><td><code>field.name.uncapitalize</code></td><td><code>tool.uncapitalize(it.fieldName())</code></td><td><code>Barcode</code> → <code>barcode</code></td></tr><tr><td><code>field.name.capitalize</code></td><td><code>tool.capitalize(it.fieldName())</code></td><td><code>barcode</code> → <code>Barcode</code></td></tr><tr><td><code>field.name.camel-case</code></td><td><code>tool.toCamelCase(it.fieldName())</code></td><td><code>user_name</code> → <code>userName</code></td></tr><tr><td><code>field.name.pascal-case</code></td><td><code>tool.toPascalCase(it.fieldName())</code></td><td><code>user_name</code> → <code>UserName</code></td></tr><tr><td><code>field.name.snake-case</code></td><td><code>tool.toSnakeCase(it.fieldName())</code></td><td><code>URLValue</code> → <code>url_value</code></td></tr><tr><td><code>field.name.kebab-case</code></td><td><code>tool.toKebabCase(it.fieldName())</code></td><td><code>URLValue</code> → <code>url-value</code></td></tr><tr><td><code>field.name.lower-dot-case</code></td><td><code>tool.toLowerDotCase(it.fieldName())</code></td><td><code>URLValue</code> → <code>url.value</code></td></tr><tr><td><code>field.name.upper-snake-case</code></td><td><code>tool.upperCase(tool.toSnakeCase(it.fieldName()))</code></td><td><code>URLValue</code> → <code>URL_VALUE</code></td></tr><tr><td><code>field.name.upper-kebab-case</code></td><td><code>tool.upperCase(tool.toKebabCase(it.fieldName()))</code></td><td><code>URLValue</code> → <code>URL-VALUE</code></td></tr></tbody></table><p>每个扩展就是一条 <code>field.name</code> Groovy 规则，没有新增 rule key、parser、设置项或配置语法。</p><h2 id="启用扩展" tabindex="-1">启用扩展 <a class="header-anchor" href="#启用扩展" aria-label="Permalink to &quot;启用扩展&quot;">​</a></h2><p>在 <strong>Extensions</strong> 标签页中勾选需要的扩展：</p><p><kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>Extensions</kbd></p><p>勾选结果会以逗号分隔的 <code>extensionConfigs</code> 值保存，因此也可以在规则文件中设置。9 个扩展写入的是同一个 <code>field.name</code> key，<strong>一次只启用一个</strong>。</p><h2 id="缩写词处理" tabindex="-1">缩写词处理 <a class="header-anchor" href="#缩写词处理" aria-label="Permalink to &quot;缩写词处理&quot;">​</a></h2><p><code>toCamelCase</code>、<code>toSnakeCase</code>、<code>toKebabCase</code>、<code>toPascalCase</code> 和 <code>toLowerDotCase</code> 共用同一个分词器：分隔符（<code>_</code>、<code>-</code>、<code>.</code>、空格）、驼峰起伏和缩写词边界都算词边界， 因此 <code>URLValue</code> 会拆成 <code>url</code> + <code>value</code>。这也是 System.Text.Json、Newtonsoft.Json、 Rails、Pydantic、lodash 以及 Jackson <code>KebabCaseStrategy</code> 采用的主流边界。</p><p><code>tool.camel2Underline</code> 是保留的旧行为：它遵循 Jackson <code>SnakeCaseStrategy</code>， 连续大写字母不拆分，<code>URLValue</code> 会得到 <code>urlvalue</code>。已有规则按名字调用它时行为不变； <code>field.name.snake-case</code> 扩展使用的是 <code>toSnakeCase</code>。参见 <a href="/zh/settings/tools/tool">tool</a>。</p><p>自 v3.2.7 起，bean 属性名按 <code>java.beans.Introspector.decapitalize</code> 解析： <code>getURLValue()</code> 解析为 <code>URLValue</code> 而不是 <code>uRLValue</code>。字段与其 accessor 因而会合并， 只导出一个属性 —— 对同时声明 <code>public String Barcode</code> 和 <code>getBarcode()</code> 的生成类很有用。 启用 <code>field.name.uncapitalize</code> 后两者都会映射为 <code>barcode</code>。</p><h2 id="自定义规则" tabindex="-1">自定义规则 <a class="header-anchor" href="#自定义规则" aria-label="Permalink to &quot;自定义规则&quot;">​</a></h2><p>如果 9 个预置策略都不合适，可以在规则文件里直接用相同的 <code>tool</code> 方法：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">field.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    return tool.toSnakeCase(it.fieldName())</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre></div><p>规则说明见 <a href="/zh/settings/rules/field_name">field.name</a>，完整辅助方法见 <a href="/zh/settings/tools">脚本工具</a>。</p><h2 id="参见" tabindex="-1">参见 <a class="header-anchor" href="#参见" aria-label="Permalink to &quot;参见&quot;">​</a></h2><ul><li><a href="/zh/framework/field-order">字段排序扩展</a></li><li><a href="/zh/settings/tools/tool">tool</a> —— 字符串与命名工具</li></ul>',19)])])}const u=d(c,[["render",s]]);export{m as __pageData,u as default};
